CREATE TABLE charmville_creature_combat(creature_id uuid PRIMARY KEY REFERENCES charmville_creature_entities(id),attack_iv integer NOT NULL,defense_iv integer NOT NULL,speed_iv integer NOT NULL,move_id integer NOT NULL,pp integer NOT NULL CHECK(pp>=0));
CREATE TABLE charmville_wild_combat(encounter_id uuid PRIMARY KEY REFERENCES charmville_encounters(id),attack_iv integer NOT NULL,defense_iv integer NOT NULL,speed_iv integer NOT NULL,pp integer NOT NULL CHECK(pp>=0),turn bigint NOT NULL DEFAULT 0,controller_id bigint REFERENCES plankspace_profiles(id),partner_id uuid REFERENCES charmville_creature_entities(id));
CREATE TABLE charmville_battle_receipts(profile_id bigint NOT NULL REFERENCES plankspace_profiles(id),request_id uuid NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(profile_id,request_id));
